// Nombre minimal de pièces pour composer `amount`.
export function minCoins(coins, amount) {
  // BUG : stratégie gloutonne — sous-optimale pour certains jeux de pièces.
  const sorted = [...coins].sort((a, b) => b - a);
  let count = 0, rem = amount;
  for (const c of sorted) while (rem >= c) { rem -= c; count += 1; }
  return rem === 0 ? count : -1;
}

